static FATAL_PANIC_EXITING: AtomicBool = AtomicBool::new(false);
const MM_SPORT_DISCOVERY_SNAPSHOT_PATH: &str = "mm_sport_discovery_snapshot.json";
const MM_SPORT_DISCOVERY_SNAPSHOT_VERSION: u32 = 1;
const MM_SPORT_DISCOVERY_SNAPSHOT_MIN_SPORTS: usize = 100;
const MM_SPORT_DISCOVERY_SNAPSHOT_MAX_AGE_MS: i64 = 2 * 60 * 60 * 1_000;

fn install_fatal_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        if FATAL_PANIC_EXITING.swap(true, AtomicOrdering::SeqCst) {
            std::process::abort();
        }

        let ts = Utc::now().to_rfc3339();
        let thread = std::thread::current();
        let thread_name = thread.name().unwrap_or("unnamed");
        let panic_message = info
            .payload()
            .downcast_ref::<&str>()
            .map(|s| (*s).to_string())
            .or_else(|| info.payload().downcast_ref::<String>().cloned())
            .unwrap_or_else(|| "panic payload unavailable".to_string());
        let location = info
            .location()
            .map(|loc| format!("{}:{}:{}", loc.file(), loc.line(), loc.column()))
            .unwrap_or_else(|| "unknown".to_string());
        let line = format!(
            "fatal runtime panic ts={ts} thread={thread_name} location={location} message={panic_message}"
        );

        let _ = writeln!(io::stderr(), "{line}");
        if let Ok(mut file) = OpenOptions::new()
            .create(true)
            .append(true)
            .open("evpoly-fatal-panic.log")
        {
            let _ = writeln!(file, "{line}");
            let _ = file.flush();
        }
        log_event(
            "runtime_fatal_panic",
            json!({
                "thread": thread_name,
                "location": location,
                "message": panic_message,
            }),
        );

        std::process::exit(101);
    }));
}

