        let guard = evaluate_endgame_v1_proxy_direction_guard(
            coinbase_open,
            coinbase_live,
            binance_open,
            binance_live_up,
        );
        assert!(!guard.skip);
        assert_eq!(guard.reason, "proxy_direction_agrees");

        let binance_live_down = Some(EndgameV1SpotSample {
            source_ts_ms: 2_000,
            price: 99.5,
        });
        let guard = evaluate_endgame_v1_proxy_direction_guard(
            coinbase_open,
            coinbase_live,
            binance_open,
            binance_live_down,
        );
        assert!(guard.skip);
        assert_eq!(guard.reason, "proxy_direction_mismatch");
