    #[test]
    fn mm_sport_active_scope_keeps_hot_state_and_caps_fresh_candidates() {
        let now_ms = 2_000_000_000_000_i64;
        let discovered_markets = vec![
            mm_sport_test_market("cond-a", 900.0, now_ms + 86_400_000),
            mm_sport_test_market("cond-b", 800.0, now_ms + 86_400_000),
            mm_sport_test_market("cond-c", 700.0, now_ms + 86_400_000),
            mm_sport_test_market("cond-d", 600.0, now_ms + 86_400_000),
            mm_sport_test_market("cond-e", 500.0, now_ms + 86_400_000),
            mm_sport_test_market("cond-f", 400.0, now_ms + 86_400_000),
        ];
        let mut fallback_exit = std::collections::HashMap::new();
        fallback_exit.insert(
            "cond-z".to_string(),
            mm_sport_test_market("cond-z", 1.0, now_ms + 3_600_000),
        );
        let mut open_orders = std::collections::HashMap::new();
        open_orders.insert(
            "cond-f".to_string(),
            vec![mm_sport_test_pending_row("cond-f", "cond-f_up")],
        );
        let inventory_conditions =
            std::collections::HashSet::from(["cond-e".to_string(), "cond-z".to_string()]);
        let entry_pause =
            std::collections::HashMap::from([("cond-d".to_string(), now_ms + 60_000)]);
        let bust_pause = std::collections::HashMap::new();
        let ratio_pause = std::collections::HashMap::new();
        let quote_expiry =
            std::collections::HashMap::from([("cond-c".to_string(), (now_ms + 60_000, 300))]);
        let no_exit_side_pause = std::collections::HashMap::new();

        let active = mm_sport_build_active_markets(
            discovered_markets.as_slice(),
            &fallback_exit,
            &open_orders,
            &inventory_conditions,
            &entry_pause,
            &bust_pause,
            &ratio_pause,
            &quote_expiry,
            &no_exit_side_pause,
            now_ms,
            28_800,
            2,
            0,
        );

        let conditions = active
            .iter()
            .map(|market| market.condition_id.as_str())
            .collect::<std::collections::HashSet<_>>();
        assert!(conditions.contains("cond-a"));
        assert!(conditions.contains("cond-b"));
        assert!(conditions.contains("cond-d"));
        assert!(conditions.contains("cond-e"));
        assert!(conditions.contains("cond-f"));
        assert!(conditions.contains("cond-z"));
        assert!(conditions.contains("cond-d") && conditions.contains("cond-e"));
        assert!(conditions.contains("cond-c"));
    }

    #[test]
    fn mm_sport_scan_selection_keeps_hot_and_rotates_fresh_candidates() {
        let active = vec![
            mm_sport_test_market("hot-open", 1000.0, 2_000_000_086_400_i64),
            mm_sport_test_market("fresh-a", 900.0, 2_000_000_086_400_i64),
            mm_sport_test_market("fresh-b", 800.0, 2_000_000_086_400_i64),
            mm_sport_test_market("fresh-c", 700.0, 2_000_000_086_400_i64),
        ];
        let hot = std::collections::HashSet::from(["hot-open".to_string()]);
        let mut cursor = 0usize;

        let first = mm_sport_select_markets_for_scan(active.as_slice(), &hot, 2, &mut cursor);
        let first_conditions = first
            .iter()
            .map(|market| market.condition_id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(first_conditions, vec!["hot-open", "fresh-a", "fresh-b"]);

        let second = mm_sport_select_markets_for_scan(active.as_slice(), &hot, 2, &mut cursor);
        let second_conditions = second
            .iter()
            .map(|market| market.condition_id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(second_conditions, vec!["hot-open", "fresh-c", "fresh-a"]);
    }

    #[test]
    fn mm_sport_active_scope_applies_separate_sport_and_nonsport_caps() {
        let now_ms = 2_000_000_000_000_i64;
        let mut nonsport_a = mm_sport_test_market("nonsport-a", 1100.0, now_ms + 86_400_000);
        nonsport_a.is_sports_market = false;
        let mut nonsport_b = mm_sport_test_market("nonsport-b", 700.0, now_ms + 86_400_000);
        nonsport_b.is_sports_market = false;
        let discovered_markets = vec![
            mm_sport_test_market("sport-a", 1000.0, now_ms + 86_400_000),
            mm_sport_test_market("sport-b", 900.0, now_ms + 86_400_000),
            mm_sport_test_market("sport-hot", 100.0, now_ms + 86_400_000),
            nonsport_a,
            nonsport_b,
        ];
        let open_orders = std::collections::HashMap::from([(
            "sport-hot".to_string(),
            vec![mm_sport_test_pending_row("sport-hot", "sport-hot_up")],
        )]);
        let active = mm_sport_build_active_markets(
            discovered_markets.as_slice(),
            &std::collections::HashMap::new(),
            &open_orders,
            &std::collections::HashSet::new(),
            &std::collections::HashMap::new(),
            &std::collections::HashMap::new(),
            &std::collections::HashMap::new(),
            &std::collections::HashMap::new(),
            &std::collections::HashMap::new(),
            now_ms,
            28_800,
            1,
            1,
        );

        let conditions = active
            .iter()
            .map(|market| market.condition_id.as_str())
            .collect::<std::collections::HashSet<_>>();
        assert!(conditions.contains("sport-hot"));
        assert!(conditions.contains("sport-a"));
        assert!(conditions.contains("nonsport-a"));
        assert!(!conditions.contains("sport-b"));
        assert!(!conditions.contains("nonsport-b"));
    }

